// A quantum runs to its ordinary completion, keeping guest time and input
// deterministic. Only the host's batch ends early: the interface can publish
// that frame, and unexecuted quanta are returned to the bounded pacing budget.
func executeFrameBatch(request frameRunRequest, wallNow func() time.Time) frameRunResult {
	result := frameRunResult{generation: request.generation, startedAt: request.startedAt}
	deadline := wallNow().Add(frameWorkerBatchTime)
	for range request.owed {
		if result.err = request.backend.RunFrame(context.Background()); result.err != nil {
			break
		}
		result.completedQuanta++
		if request.uiPriority {
			time.Sleep(uiPriorityFrameRest)
		}
		if !wallNow().Before(deadline) {
			break
		}
	}
	result.guestAdvanced = time.Duration(result.completedQuanta) * request.quantum
	if result.err == nil {
		result.deferredGuest = time.Duration(request.owed-result.completedQuanta) * request.quantum
	}
	return result
}

